{
  "aggregate": "master_question",
  "pipeline": {{
    (() => {
      const targetDomains = this.params.domains || [];
      const targetOrigins = this.params.origins || [];
      const onlyWrong = this.params.onlyWrong === true || this.params.onlyWrong === "true";
      const bookmarksOnly = this.params.bookmarksOnly === true || this.params.bookmarksOnly === "true";

      let matchConditions = {};

      // 1. Domain-Filter
      if (Array.isArray(targetDomains)) {
        if (targetDomains.length > 0) {
          matchConditions["domain"] = { "$in": targetDomains };
        } else {
          matchConditions["domain"] = { "$in": [] }; // Nichts matchen, wenn leer
        }
      } else if (typeof targetDomains === "string" && targetDomains.trim() !== "") {
        matchConditions["domain"] = targetDomains;
      }

      // 2. Origin-Filter
      if (Array.isArray(targetOrigins) && targetOrigins.length > 0) {
        matchConditions["origin"] = { "$in": targetOrigins };
      }

      // 3. Zusätzlicher Filter für countWrong > 0, falls true
      if (onlyWrong) {
        matchConditions["countWrong"] = { "$exists": true, "$gt": 0 };
      }

      let pipeline = [];

      // `$match` mit allen Basis-Bedingungen
      pipeline.push({
        "$match": matchConditions
      });

      // 4. Lookup (Join) mit Typkonvertierung von ObjectId (_id) zu String
      pipeline.push({
        "$lookup": {
          "from": "bookmark",
          "let": { "idString": { "$toString": "$_id" } },
          "pipeline": [
            {
              "$match": {
                "$expr": { "$eq": ["$questionId", "$$idString"] }
              }
            }
          ],
          "as": "bookmarkMatch"
        }
      });

      // 5. Feld `hasBookmark` ("true" oder "no") basierend auf dem Lookup setzen
      pipeline.push({
        "$addFields": {
          "hasBookmark": {
            "$cond": {
              "if": { "$gt": [{ "$size": "$bookmarkMatch" }, 0] },
              "then": "true",
              "else": "no"
            }
          }
        }
      });

      // Temporäres Array für eine saubere Pipeline entfernen
      pipeline.push({
        "$project": {
          "bookmarkMatch": 0
        }
      });

      // 6. Filter falls 'bookmarksOnly' aktiv ist
      if (bookmarksOnly) {
        pipeline.push({
          "$match": {
            "hasBookmark": "true"
          }
        });
      }

      // 7. Danach nach Domain gruppieren und zählen
      pipeline.push(
        {
          "$group": {
            "_id": "$domain",
            "total": { "$sum": 1 }
          }
        },
        {
          "$sort": { "_id": 1 }
        }
      );

      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": 100
  }
}
